**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("wyniki.txt");
    int P;
    plik >> P;

    int minPowyzej = 0, maxPonizej = 0;
    bool znA = false, znB = false;
    int ileA = 0, ileB = 0;
    int x;
    while (plik >> x) {
        if (x > P) {
            if (!znA || x < minPowyzej) { minPowyzej = x; znA = true; }
            ileA++;
        } else {
            if (!znB || x > maxPonizej) { maxPonizej = x; znB = true; }
            ileB++;
        }
    }

    cout << "Prog: " << P << endl;
    cout << "a) Min wsrod > " << P << ": ";
    if (znA) cout << minPowyzej << " (z " << ileA << " elementow)" << endl;
    else cout << "brak" << endl;
    cout << "b) Max wsrod <= " << P << ": ";
    if (znB) cout << maxPonizej << " (z " << ileB << " elementow)" << endl;
    else cout << "brak" << endl;
    return 0;
}
```

**Wyjasnienie**: Skan z podzielem na dwie grupy wzgledem progu. Flagi zapewniaja bezpieczna inicjalizacje. Elementy rowne progowi trafiaja do grupy <= P.

Weryfikacja:
- Prog = 50
- Dane: 23, 67, 45, 89, 50, 34, 72, 55, 18, 91 (10 elementow)
- Elementy > 50: 67, 89, 72, 55, 91 -> min = 55, ile = 5
- Elementy <= 50: 23, 45, 50, 34, 18 -> max = 50, ile = 5
